package handler

const pageHTML = `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>潮闸值守</title><style>body{font:16px system-ui;margin:2rem;background:#eef4f1;color:#17352d}main{max-width:960px;margin:auto}header{display:flex;justify-content:space-between;align-items:center}section{background:white;margin:1rem 0;padding:1rem;border:1px solid #c8ddd5;border-radius:8px}button{background:#176b58;color:white;border:0;padding:.6rem 1rem;border-radius:4px}table{width:100%;border-collapse:collapse}td,th{padding:.5rem;border-bottom:1px solid #ddd;text-align:left}.muted{color:#6e7f79}</style></head><body><main><header><h1>潮闸联控值守</h1><span class="muted">tide-gate-ops</span></header><section><h2>站点与闸门</h2><div id="gates">正在读取...</div></section><section><h2>开放告警</h2><div id="alarms">正在读取...</div></section><section><h2>最近读数</h2><div id="readings">提交采集数据后显示</div></section></main><script>async function load(){let [g,a]=await Promise.all([fetch('/api/gates').then(r=>r.json()),fetch('/api/alarms').then(r=>r.json())]);document.querySelector('#gates').innerHTML='<table><tr><th>闸门</th><th>状态</th><th>开度</th></tr>'+g.map(x=>'<tr><td>'+x.name+'</td><td>'+x.status+'</td><td>'+x.opening_percent+'%</td></tr>').join('')+'</table>';document.querySelector('#alarms').innerHTML=a.length?a.map(x=>'<p><b>'+x.severity+'</b> '+x.message+' <span class="muted">'+x.state+'</span></p>').join(''):'暂无开放告警'}load();setInterval(load,5000)</script></body></html>`
